-- Preserve prior payment scopes; classify only provable completion scopes. Idempotent.
CREATE TABLE IF NOT EXISTS reservation_payment_scopes_v2 (
 target_type TEXT NOT NULL CHECK(target_type IN ('booking','inquiry')),
 target_ref TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('unpaid','reservation_paid','venue_paid','food_paid','venue_fully_paid','fully_paid','partial_paid','needs_review')),
 version INTEGER NOT NULL DEFAULT 1,
 updated_at TEXT NOT NULL,
 PRIMARY KEY(target_type,target_ref)
);
INSERT OR IGNORE INTO reservation_payment_scopes_v2(target_type,target_ref,status,version,updated_at)
SELECT p.target_type,p.target_ref,CASE WHEN p.status='fully_paid' THEN CASE WHEN ((json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering') IS NOT NULL AND json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering') NOT IN ('null','object')) OR (json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception') IS NOT NULL AND json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception') NOT IN ('null','object')) OR (json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail') IS NOT NULL AND json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail') NOT IN ('null','object'))) THEN 'needs_review' WHEN i.ref IS NULL OR NOT json_valid(i.data) THEN 'needs_review' WHEN ((COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status'),'pending')<>'cancelled') OR (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.status'),'pending')<>'cancelled') OR (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.status'),'pending')<>'cancelled')) AND ((NOT (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status'),'pending')<>'cancelled') OR ((COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status'),'pending')<>'cancelled') AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status') IN ('confirmed','ordered','completed') AND (json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.total'))>0 AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.included_catering_amount')=(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.total')))) AND (NOT (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.status'),'pending')<>'cancelled') OR ((COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.status'),'pending')<>'cancelled') AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.status') IN ('confirmed','ordered','completed') AND (json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.total'))>0 AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.included_reception_amount')=(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.total')))) AND (NOT (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.status'),'pending')<>'cancelled') OR ((COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.status'),'pending')<>'cancelled') AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.status') IN ('confirmed','ordered','completed') AND (CASE WHEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.vat_excluded')=1 THEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.total') ELSE json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.price') END)>0 AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.included_cocktail_amount')=(CASE WHEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.vat_excluded')=1 THEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.total') ELSE json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.price') END)))) AND (CAST(COALESCE(b.amount,json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.total')) AS REAL)>=(CASE WHEN (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status'),'pending')<>'cancelled') THEN COALESCE((json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.total')),0) ELSE 0 END+CASE WHEN (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.status'),'pending')<>'cancelled') THEN COALESCE((json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.total')),0) ELSE 0 END+CASE WHEN (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.status'),'pending')<>'cancelled') THEN COALESCE((CASE WHEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.vat_excluded')=1 THEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.total') ELSE json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.price') END),0) ELSE 0 END)) AND NOT EXISTS(SELECT 1 FROM catering_orders co WHERE (co.inquiry_ref=i.ref OR co.booking_code=b.booking_code) AND co.status<>'cancelled' AND COALESCE(json_extract(CASE WHEN json_valid(co.data) THEN co.data ELSE '{}' END,'$.removed'),0)=0 AND NOT(COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.order_ref'),'')=co.ref AND ((COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status'),'pending')<>'cancelled') AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status') IN ('confirmed','ordered','completed') AND (json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.total'))>0 AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.included_catering_amount')=(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.total'))) AND json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.total')=co.total)) THEN 'fully_paid' WHEN NOT((COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.catering.status'),'pending')<>'cancelled') OR (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.reception.status'),'pending')<>'cancelled') OR (COALESCE(json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail'),'')='object' AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.removed'),0)=0 AND COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.cocktail.status'),'pending')<>'cancelled')) AND NOT EXISTS(SELECT 1 FROM catering_orders co WHERE (co.inquiry_ref=i.ref OR co.booking_code=b.booking_code) AND co.status<>'cancelled' AND COALESCE(json_extract(CASE WHEN json_valid(co.data) THEN co.data ELSE '{}' END,'$.removed'),0)=0) AND NOT(instr((COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.message'),'')||COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.summary'),'')),'뷔페')>0 OR instr((COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.message'),'')||COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.summary'),'')),'케이터링')>0 OR instr((COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.message'),'')||COALESCE(json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.summary'),'')),'칵테일')>0) AND NOT EXISTS(SELECT 1 FROM json_each(CASE WHEN json_type((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.quote_input.extras')='array' THEN json_extract((CASE WHEN json_valid(i.data) THEN i.data ELSE '{}' END),'$.quote_input.extras') ELSE '[]' END) ex WHERE json_extract(CASE WHEN json_valid(ex.value) THEN ex.value ELSE '{}' END,'$.kind') IN ('catering','reception','cocktail')) THEN 'venue_fully_paid' ELSE 'needs_review' END ELSE p.status END,CASE WHEN p.status='fully_paid' THEN p.version+1 ELSE p.version END,p.updated_at
FROM reservation_payment_scopes p LEFT JOIN bookings b ON p.target_type='booking' AND b.booking_code=p.target_ref
LEFT JOIN inquiries i ON i.ref=CASE WHEN p.target_type='booking' THEN b.inquiry_ref ELSE p.target_ref END;
CREATE TRIGGER IF NOT EXISTS reservation_payment_scope_v2_inherit AFTER INSERT ON bookings WHEN NEW.inquiry_ref IS NOT NULL
BEGIN
 INSERT OR IGNORE INTO reservation_payment_scopes_v2(target_type,target_ref,status,version,updated_at)
 SELECT 'booking',NEW.booking_code,status,1,updated_at FROM reservation_payment_scopes_v2 WHERE target_type='inquiry' AND target_ref=NEW.inquiry_ref;
END;
